const $=s=>document.querySelector(s);const safe=n=>String(n).padStart(2,'0');
function renderRoster(){ $('#roster').innerHTML=heroes.map(h=>`<div class="hero-card ${h.id===state.selectedHero?'selected':''}" data-hero="${h.id}" title="${h.deployed?'Görevden çıkar':'Göreve al'}"><div class="portrait">${h.icon}</div><div><div class="hero-name">${h.name}</div><div class="hero-class">${h.cls}</div></div><div class="level">${h.deployed?'SAHADA':'SV.'+h.level}</div></div>`).join('');$('#deployCount').innerHTML=`${heroes.filter(h=>h.deployed).length} / 4`;$('#rosterSub').textContent='09 KAHRAMAN';document.querySelectorAll('.hero-card').forEach(el=>el.onclick=()=>{let h=heroes.find(a=>a.id===el.dataset.hero);state.selectedHero=h.id;let deployed=heroes.filter(a=>a.deployed).length;if(h.deployed){if(deployed===1){toast('En az bir yoldaş sahada kalmalı.');return}h.deployed=false;toast(h.name+' görevden ayrıldı.')}else if(deployed>=4){toast('Sahada en fazla 4 yoldaş olabilir. Önce birini görevden al.');return}else if(state.gold>=h.cost){state.gold-=h.cost;h.deployed=true;updateGold();toast(h.name+' sefere katıldı! (-'+h.cost+' altın)')}else{toast('Bu yoldaşı göreve almak için '+h.cost+' altın gerekli.');return}render()})}
function renderItems(){const content=$('#tabContent');if(state.tab==='inventory'){const list=state.inventory;content.innerHTML=`<div class="inventory-head"><p>Bulunan ganimetler · ${list.length} eşya</p><button class="filter" id="sortBtn">SIRALA ↕</button></div><div class="items-grid">${list.length?list.map(it=>{let t=it.type;return `<div class="item ${state.selectedItem===it.id?'active':''}" data-item="${it.id}" style="--rarity:${rarityColors[it.rarity]}"><i class="rarity"></i><div class="item-icon">${icons[t]}</div><div class="item-name">${names[t]}</div><div class="item-meta">${rarityNames[it.rarity]} · Sv.${it.level}</div></div>`}).join(''):'<div class="empty">Envanter boş. Düşmanları yenerek ganimet topla.</div>'}</div><div class="item-details" id="itemDetails">${selectedItemHTML()}</div>`;document.querySelectorAll('.item').forEach(el=>el.onclick=()=>{state.selectedItem=Number(el.dataset.item);renderItems()});$('#sortBtn')?.addEventListener('click',()=>{state.inventory.sort((a,b)=>b.rarity-a.rarity);renderItems()});$('#equipBtn')?.addEventListener('click',equipSelected);$('#meltBtn')?.addEventListener('click',meltSelected)}else if(state.tab==='equipment'){let h=heroes.find(x=>x.id===state.selectedHero);content.innerHTML=`<div class="inventory-head"><p>${h.name} · Kuşanılmış ekipman</p><span class="class-pill">${h.cls}</span></div><div class="items-grid">${['Silah','Zırh','Tılsım'].map((slot,i)=>{let item=state.equipped[h.id]?.[i];return `<div class="item" style="min-height:110px;cursor:default"><div class="item-meta" style="margin-bottom:8px">${slot.toLocaleUpperCase('tr')}</div><div class="item-icon">${item?icons[item.type]:'◇'}</div><div class="item-name">${item?names[item.type]:'Boş yuva'}</div><div class="item-meta">${item?rarityNames[item.rarity]+' · Sv.'+item.level:'Envanterden kuşan'}</div></div>`}).join('')}</div><div class="item-details"><div class="detail-text"><strong>Ekipman etkisi</strong><small>Aktif ekipman karakter özelliklerini güçlendirir.</small></div><button class="btn" onclick="state.tab='inventory';render()">ENVANTERE DÖN</button></div>`}else{content.innerHTML=`<div class="inventory-head"><p>Sefer düzeni ve ganimet döngüsü</p><span class="class-pill">TAM OTOMATİK</span></div><div style="padding:8px 3px;color:#c0c5b7;line-height:1.75;font-size:12px"><b style="color:#e1c47f">Savaş yönetimi yok.</b> Dört kişilik ekibin düşman dalgalarına karşı kendi kendine savaşır. Sen yoldaşları göreve alır, ganimeti kuşanır veya eritirsin.<br><br><b style="color:#e1c47f">Ganimet döngüsü</b><br>Her dalga altın ve ekipman bırakır. Kullanmadığın eşyayı erit; altını yeni yoldaşlara ve yetenek geliştirmelerine yatır.<br><br><b style="color:#e1c47f">Nadirlik sırası</b><br>${rarityNames.map((r,i)=>`<span style="color:${rarityColors[i]}">${r}</span>`).join(' → ')}</div><div class="item-details"><div class="detail-text"><strong>Sefer kesintisiz sürer</strong><small>Karakterler otomatik saldırır; savaşta manuel kontrol bulunmaz.</small></div></div>`}}
function selectedItemHTML(){let it=state.inventory.find(x=>x.id===state.selectedItem);if(!it)return `<div class="detail-text"><strong>Eşya seçilmedi</strong><small>Kuşanmak veya eritmek için bir ganimet seç.</small></div><div class="actions"><span class="class-pill">${state.inventory.length} EŞYA</span></div>`;return `<div class="detail-text"><strong style="color:${rarityColors[it.rarity]}">${names[it.type]} · ${rarityNames[it.rarity]}</strong><small>Sv.${it.level} · ${gearTypes[it.type]} · ${gearStats[it.type]}</small></div><div class="actions"><button class="btn primary" id="equipBtn">KUŞAN</button><button class="btn danger" id="meltBtn">ERİT · +${meltValue(it)}◈</button></div>`}
function meltValue(it){return 12+it.level*5+it.rarity*9}
function equipSelected(){const it=state.inventory.find(x=>x.id===state.selectedItem);if(!it)return;let h=heroes.find(a=>a.id===state.selectedHero);let slot=it.type===0||it.type===3||it.type===5||it.type===6?0:it.type===1||it.type===4||it.type===7||it.type===10?1:2;let old=state.equipped[h.id][slot];if(old)state.inventory.push(old);state.equipped[h.id][slot]=it;state.inventory=state.inventory.filter(a=>a.id!==it.id);state.selectedItem=null;toast(names[it.type]+' '+h.name+' tarafından kuşanıldı.');render()}
function meltSelected(){let it=state.inventory.find(x=>x.id===state.selectedItem);if(!it)return;let gain=meltValue(it);state.gold+=gain;state.inventory=state.inventory.filter(a=>a.id!==it.id);state.selectedItem=null;updateGold();toast(names[it.type]+' eritildi: +'+gain+' altın');render()}
function renderHero(){let h=heroes.find(x=>x.id===state.selectedHero);$('#detailClass').textContent=h.role.toLocaleUpperCase('tr');let equip=Object.values(state.equipped[h.id]||{}).filter(Boolean);let bonus=equip.reduce((n,x)=>n+x.level*3+x.rarity*2,0);$('#heroDetail').innerHTML=`<div class="hero-summary"><div class="big-portrait">${h.icon}</div><div><h4>${h.name}</h4><p>${h.cls} · Seviye ${h.level}</p></div></div><div class="stats">${[['CAN',h.hp+bonus,250,'♥'],['SALDIRI',h.atk+Math.floor(bonus/2),70,'⚔'],['SAVUNMA',h.def+Math.floor(bonus/3),40,'⬡']].map(s=>`<div class="stat-row"><span>${s[0]} <div class="stat-line"><i style="width:${Math.min(100,s[1]/s[2]*100)}%"></i></div></span><b>${s[1]}</b></div>`).join('')}</div><div class="skills-head"><strong>Yetenekler</strong><small class="level">GELİŞİM</small></div><div class="skill"><span class="skill-icon">${h.skillIcon}</span><div class="skill-info"><b>${h.skill}</b><small>Seviye ${h.level} · ${h.desc}</small></div><button class="upgrade" data-upgrade="${h.id}">+ GELİŞTİR<br>${45+h.level*20}◈</button></div><p class="note">Yetenekler savaşta otomatik kullanılır. Geliştirme maliyeti: ${45+h.level*20} altın. Savaş sırasında komut verilemez.</p>`;document.querySelectorAll('[data-upgrade]').forEach(b=>b.onclick=()=>{let hero=heroes.find(a=>a.id===b.dataset.upgrade),cost=45+hero.level*20;if(state.gold<cost){toast('Yeterli altın yok.');return}state.gold-=cost;hero.level++;hero.atk+=3;hero.hp+=8;updateGold();toast(hero.skill+' geliştirildi!');render()})}
function render(){renderRoster();renderItems();renderHero();$('#itemCount').textContent=safe(state.inventory.length)}function updateGold(){$('#gold').textContent=state.gold}
document.querySelectorAll('.tab').forEach(b=>b.onclick=()=>{state.tab=b.dataset.tab;document.querySelectorAll('.tab').forEach(x=>x.classList.toggle('active',x===b));renderItems()});let toastTimer;function toast(text){let el=$('#toast');el.textContent=text;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2100)}

