const rarityNames=['Sıradan','Sıra dışı','Nadir','Destansı','Efsanevi','Mitik','Yıldız','Ay','Güneş','Hiçlik'],rarityColors=['#92958c','#77b979','#5f9fe0','#b17ade','#e6a94f','#ed6c78','#78d8e6','#9b9eff','#f1dc66','#f3f2ff'];
const heroes=[
{id:'warrior',name:'Boran',cls:'Tank Savaşçı',icon:'🛡️',role:'Ön Saf',hp:160,atk:21,def:18,level:4,deployed:true,skill:'Kalkan Darbesi',skillIcon:'⬡',cost:65,desc:'Ön safta hasarı üstlenir.'},{id:'mage',name:'Lâl',cls:'Büyücü',icon:'🧙',role:'Büyü Hasarı',hp:82,atk:38,def:5,level:3,deployed:true,skill:'Alev Küresi',skillIcon:'✹',cost:70,desc:'Düşman saflarına büyü savurur.'},{id:'archer',name:'Ekin',cls:'Okçu',icon:'🏹',role:'Uzak Menzil',hp:95,atk:27,def:7,level:3,deployed:true,skill:'Çifte Ok',skillIcon:'➶',cost:65,desc:'Güvenli mesafeden seri atış yapar.'},{id:'healer',name:'Mira',cls:'Şifacı Destek',icon:'🌿',role:'İyileştirme',hp:108,atk:12,def:9,level:2,deployed:false,skill:'Şifa Işığı',skillIcon:'✚',cost:60,desc:'Yoldaşlarının yaralarını sarar.'},{id:'heavy',name:'Demirhan',cls:'Ağır Tank',icon:'⛨',role:'Ağır Savunma',hp:220,atk:17,def:26,level:2,deployed:false,skill:'Sarsılmaz Duruş',skillIcon:'◈',cost:80,desc:'Takımın en sağlam savunma hattı.'},{id:'dagger',name:'Saye',cls:'Hançer',icon:'🗡️',role:'Suikastçı',hp:88,atk:45,def:6,level:1,deployed:false,skill:'Gölge Hamlesi',skillIcon:'☽',cost:75,desc:'Zayıf hedeflere ölümcül darbeler indirir.'},{id:'darkmage',name:'Nâzım',cls:'Kara Büyücü',icon:'🌑',role:'Kara Büyü',hp:90,atk:40,def:6,level:1,deployed:false,skill:'Ruh Sömürüsü',skillIcon:'◉',cost:80,desc:'Düşman yaşamını kendi gücüne katar.'},{id:'xbow',name:'Tuna',cls:'Arbaletçi',icon:'🏹',role:'Delici Atış',hp:101,atk:32,def:8,level:1,deployed:false,skill:'Delici Cıvata',skillIcon:'➳',cost:70,desc:'Zırh delen cıvatalarla destek verir.'},{id:'necro',name:'Yelda',cls:'Ölü Çağıran',icon:'💀',role:'Çağırıcı',hp:92,atk:29,def:8,level:1,deployed:false,skill:'Kemik Hizmetkâr',skillIcon:'☠',cost:85,desc:'Kemik hizmetkârlarıyla savaşır.'}];
const names=['Demir Kılıç','Kül Pelerini','Aytaşı Yüzük','Kök Yay','Kor Miğfer','Sisli Hançer','Rünlü Asa','Kara Zırh','Yıldız Kolye','Güneş Mührü','Hiçlik Tacı'],icons=['⚔','◈','◉','➶','⛨','†','✦','⬡','☾','✹','♛'],gearTypes=['Silah','Zırh','Tılsım','Silah','Zırh','Silah','Silah','Zırh','Tılsım','Tılsım','Zırh'],gearStats=['Saldırı +4','Savunma +3','Can +12','Saldırı +5','Savunma +5','Saldırı +7','Büyü +6','Savunma +8','Can +20','Saldırı +11','Can +35'];
let state={gold:260,wave:3,kills:12,selectedHero:'warrior',selectedItem:null,tab:'inventory',sound:false,inventory:[{id:1,type:0,rarity:2,level:2},{id:2,type:2,rarity:1,level:1},{id:3,type:4,rarity:3,level:3},{id:4,type:1,rarity:0,level:1},{id:5,type:6,rarity:4,level:3},{id:6,type:5,rarity:2,level:2},{id:7,type:3,rarity:1,level:1},{id:8,type:8,rarity:3,level:2}],equipped:Object.fromEntries(heroes.map(h=>[h.id,[null,null,null]]))};
const $=s=>document.querySelector(s),safe=n=>String(n).padStart(2,'0');
