const rarityNames=['Sıradan','Sıra dışı','Nadir','Destansı','Efsanevi','Mitik','Yıldız','Ay','Güneş','Hiçlik'];
const rarityColors=['#92958c','#77b979','#5f9fe0','#b17ade','#e6a94f','#ed6c78','#78d8e6','#9b9eff','#f1dc66','#f3f2ff'];
const heroes=[
{id:'warrior',name:'Boran',cls:'Tank Savaşçı',icon:'🛡️',role:'Ön Saf',hp:160,atk:21,def:18,level:4,deployed:true,skill:'Kalkan Darbesi',cost:65,desc:'Ön safta hasarı üstlenir; dayanıklılığıyla takımına zaman kazandırır.'},
{id:'mage',name:'Lâl',cls:'Büyücü',icon:'🧙',role:'Büyü Hasarı',hp:82,atk:38,def:5,level:3,deployed:true,skill:'Alev Küresi',cost:70,desc:'Uzak saflara alev küreleri fırlatır ve birden fazla düşmanı yakar.'},
{id:'archer',name:'Ekin',cls:'Okçu',icon:'🏹',role:'Uzak Menzil',hp:95,atk:27,def:7,level:3,deployed:true,skill:'Çifte Ok',cost:65,desc:'Güvenli mesafeden seri atış yapar; kritik vuruşlarıyla tanınır.'},
{id:'healer',name:'Mira',cls:'Şifacı Destek',icon:'🌿',role:'İyileştirme',hp:108,atk:12,def:9,level:2,deployed:false,skill:'Şifa Işığı',cost:60,desc:'En yaralı yoldaşını iyileştirerek ekibin ayakta kalmasını sağlar.'},
{id:'heavy',name:'Demirhan',cls:'Ağır Tank',icon:'⛨',role:'Ağır Savunma',hp:220,atk:17,def:26,level:2,deployed:false,skill:'Sarsılmaz Duruş',cost:80,desc:'Takımın en sağlam savunma hattı; yavaş ama kolay kolay düşmez.'},
{id:'dagger',name:'Saye',cls:'Hançer Ustası',icon:'🗡️',role:'Suikastçı',hp:88,atk:45,def:6,level:1,deployed:false,skill:'Gölge Hamlesi',cost:75,desc:'Zayıf hedeflere ölümcül darbeler indirir.'},
{id:'darkmage',name:'Nâzım',cls:'Kara Büyücü',icon:'🌑',role:'Kara Büyü',hp:90,atk:40,def:6,level:1,deployed:false,skill:'Ruh Sömürüsü',cost:80,desc:'Kara büyüyle düşman yaşamını kendi gücüne katar.'},
{id:'xbow',name:'Tuna',cls:'Arbaletçi',icon:'🏹',role:'Delici Atış',hp:101,atk:32,def:8,level:1,deployed:false,skill:'Delici Cıvata',cost:70,desc:'Ağır cıvatalarla zırhı deler ve uzak hedefleri bastırır.'},
{id:'necro',name:'Yelda',cls:'Ölü Çağıran',icon:'💀',role:'Çağırıcı',hp:92,atk:29,def:8,level:1,deployed:false,skill:'Kemik Hizmetkâr',cost:85,desc:'Kemik hizmetkârlarını çağırarak savaşta sayısal üstünlük kurar.'}
];
const names=['Demir Kılıç','Kül Pelerini','Aytaşı Yüzük','Kök Yay','Kor Miğfer','Sisli Hançer','Rünlü Asa','Kara Zırh','Yıldız Kolye','Güneş Mührü','Hiçlik Tacı'];
const icons=['⚔','◈','◉','➶','⛨','†','✦','⬡','☾','✹','♛'];
const gearTypes=['Silah','Zırh','Tılsım','Silah','Zırh','Silah','Silah','Zırh','Tılsım','Tılsım','Zırh'];
const gearStats=['Saldırı +8','Savunma +6','Can +18','Saldırı +7','Can +24','Saldırı +10','Saldırı +12','Savunma +9','Can +22','Saldırı +11','Savunma +14'];
let state={gold:260,wave:3,kills:12,selectedHero:'warrior',selectedItem:null,tab:'inventory',speed:1,inventory:[{id:1,type:0,rarity:2,level:2},{id:2,type:2,rarity:1,level:1},{id:3,type:4,rarity:3,level:3},{id:4,type:1,rarity:0,level:1},{id:5,type:6,rarity:4,level:3},{id:6,type:5,rarity:2,level:2},{id:7,type:3,rarity:1,level:1},{id:8,type:8,rarity:3,level:2}],equipped:Object.fromEntries(heroes.map(h=>[h.id,[null,null,null]]))};
const $=s=>document.querySelector(s),fmt=n=>new Intl.NumberFormat('tr-TR').format(n);
function toast(msg){const t=$('#toast');t.textContent=msg;t.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.classList.remove('show'),2100)}
function updateGold(){$('#gold').textContent=fmt(state.gold)}
function heroGear(h){return (state.equipped[h.id]||[]).filter(Boolean)}
function totalStat(h,key){let base=h[key];heroGear(h).forEach(i=>{let stat=gearStats[i.type];if(key==='atk'&&stat.includes('Saldırı'))base+=parseInt(stat.match(/\d+/)[0])+i.rarity; if(key==='def'&&stat.includes('Savunma'))base+=parseInt(stat.match(/\d+/)[0])+i.rarity;if(key==='hp'&&stat.includes('Can'))base+=parseInt(stat.match(/\d+/)[0])*2});return base+(h.level-1)*(key==='hp'?7:key==='atk'?2:1)}
function renderRoster(){const deployed=heroes.filter(h=>h.deployed).length;$('#deployCount').textContent=`${deployed} / 4 SAHADA`;$('#fightCount').textContent=deployed;$('#roster').innerHTML=heroes.map(h=>`<div class="hero-card ${h.id===state.selectedHero?'selected':''}" data-hero="${h.id}"><div class="portrait">${h.icon}</div><div><div class="hero-name">${h.name}</div><div class="hero-class">${h.cls}</div></div><div class="hero-level ${h.deployed?'on':''}">${h.deployed?'SAHADA':'SV.'+h.level}</div></div>`).join('');document.querySelectorAll('.hero-card').forEach(el=>el.onclick=()=>{state.selectedHero=el.dataset.hero;render()})}
function meltValue(i){return 12+i.level*5+i.rarity*9}
function selectedHTML(){let i=state.inventory.find(x=>x.id===state.selectedItem);if(!i)return `<div class="detail-text"><strong>Eşya seçilmedi</strong><small>Kuşanmak veya eritmek için bir ganimet seç.</small></div><span class="class-pill">${state.inventory.length} EŞYA</span>`;return `<div class="detail-text"><strong style="color:${rarityColors[i.rarity]}">${names[i.type]} · ${rarityNames[i.rarity]}</strong><small>Sv.${i.level} · ${gearTypes[i.type]} · ${gearStats[i.type]}</small></div><div class="actions"><button class="btn primary" id="equipBtn">KUŞAN</button><button class="btn danger" id="meltBtn">ERİT · +${meltValue(i)}◈</button></div>`}
function renderInventory(){const c=$('#tabContent');c.innerHTML=`<div class="inventory-head"><p>Bulunan ganimetler · ${state.inventory.length} eşya</p><button class="filter" id="sortBtn">NADİRE GÖRE SIRALA ↕</button></div><div class="items-grid">${state.inventory.length?state.inventory.map(i=>`<div class="item ${state.selectedItem===i.id?'active':''}" data-item="${i.id}" style="--rarity:${rarityColors[i.rarity]}"><div class="item-icon">${icons[i.type]}</div><div class="item-name">${names[i.type]}</div><div class="item-meta">${rarityNames[i.rarity]} · Sv.${i.level}</div></div>`).join(''):'<div class="empty">Envanter boş. Düşmanları yenerek ganimet topla.</div>'}</div><div class="item-details">${selectedHTML()}</div>`;document.querySelectorAll('.item[data-item]').forEach(e=>e.onclick=()=>{state.selectedItem=Number(e.dataset.item);renderInventory()});$('#sortBtn')?.addEventListener('click',()=>{state.inventory.sort((a,b)=>b.rarity-a.rarity);renderInventory()});$('#equipBtn')?.addEventListener('click',equip);$('#meltBtn')?.addEventListener('click',melt)}
function renderEquipment(){const h=heroes.find(x=>x.id===state.selectedHero);$('#tabContent').innerHTML=`<div class="inventory-head"><p>${h.name} · Kuşanılmış ekipman</p><span class="class-pill">${h.cls}</span></div><div class="equipment-list">${['Silah','Zırh','Tılsım'].map((s,slot)=>{let item=state.equipped[h.id][slot];return `<div class="equip-slot"><div class="eyebrow">${s}</div><div class="item-icon" style="color:${item?rarityColors[item.rarity]:'#718078'}">${item?icons[item.type]:'◇'}</div><b>${item?names[item.type]:'Boş yuva'}</b><small>${item?rarityNames[item.rarity]+' · '+gearStats[item.type]:'Envanterden kuşan'}</small>${item?`<button class="filter unequip" data-slot="${slot}" style="margin-top:8px">ÇIKAR</button>`:''}</div>`}).join('')}</div><div class="item-details"><div class="detail-text"><strong>Etkin özellikler</strong><small>Can ${totalStat(h,'hp')} · Saldırı ${totalStat(h,'atk')} · Savunma ${totalStat(h,'def')}</small></div><span class="class-pill">${heroGear(h).length} / 3 YUVA</span></div>`;document.querySelectorAll('.unequip').forEach(b=>b.onclick=()=>{let item=state.equipped[h.id][Number(b.dataset.slot)];state.inventory.push(item);state.equipped[h.id][Number(b.dataset.slot)]=null;toast(names[item.type]+' envantere taşındı.');render()})}

function renderHero(){const h=heroes.find(x=>x.id===state.selectedHero),hp=totalStat(h,'hp'),atk=totalStat(h,'atk'),def=totalStat(h,'def'),hire=h.deployed?'GÖREVDEN AL':'SEFERE KAT';let cost=h.deployed?0:h.cost;$('#tabContent').innerHTML=`<div class="detail-layout"><div class="detail-card"><div class="detail-top"><div class="detail-portrait">${h.icon}</div><div><h3>${h.name}</h3><p>${h.cls} · SEVİYE ${h.level}</p></div></div><p class="detail-desc">${h.desc}</p><div class="bars"><div class="barline"><span>CAN</span><div class="bar"><i style="width:${Math.min(100,hp/2.5)}%"></i></div><b>${hp}</b></div><div class="barline"><span>SALDIRI</span><div class="bar atk"><i style="width:${Math.min(100,atk*1.6)}%"></i></div><b>${atk}</b></div><div class="barline"><span>SAVUNMA</span><div class="bar def"><i style="width:${Math.min(100,def*3)}%"></i></div><b>${def}</b></div></div><div class="skill-box">✦ ${h.skill}<small>Otomatik kullanılır · ${h.role}</small></div><button class="btn ${h.deployed?'':'primary'}" id="deployBtn" style="width:100%;margin-top:11px">${hire}${cost?` · ${cost}◈`:''}</button></div><div class="detail-card"><div class="panel-heading"><div class="panel-title">Geliştirmeler</div><span class="class-pill">${heroGear(h).length} EKİPMAN</span></div><div class="upgrade-row"><div><strong>Seviye yükselt</strong><small>Temel özellikleri artırır</small></div><button class="btn upgrade-cost" data-upgrade="level">${35+h.level*20} ◈</button></div><div class="upgrade-row"><div><strong>Can eğitimi</strong><small>Kalıcı +20 can</small></div><button class="btn upgrade-cost" data-upgrade="hp">${25+h.level*10} ◈</button></div><div class="upgrade-row"><div><strong>Saldırı eğitimi</strong><small>Kalıcı +4 saldırı</small></div><button class="btn upgrade-cost" data-upgrade="atk">${30+h.level*12} ◈</button></div><div class="upgrade-row"><div><strong>Savunma eğitimi</strong><small>Kalıcı +3 savunma</small></div><button class="btn upgrade-cost" data-upgrade="def">${25+h.level*10} ◈</button></div><div class="item-details"><div class="detail-text"><strong>Geliştirme notu</strong><small>Her yükseltme altın harcar; özellikler kalıcıdır.</small></div></div></div></div>`;
$('#deployBtn').onclick=()=>toggleDeploy(h);document.querySelectorAll('[data-upgrade]').forEach(b=>b.onclick=()=>upgrade(h,b.dataset.upgrade));}
function renderGuide(){$('#tabContent').innerHTML=`<div class="inventory-head"><p>SEFER NOTLARI · KÜL ORMANI</p><span class="class-pill">OTOMATİK SAVAŞ</span></div><div class="guide"><div class="guide-card"><b>⚔ Sefer nasıl işler?</b><p>Yoldaşların düşmanları kendi başlarına bulur ve saldırır. Sen ekibini kurar, geliştirir ve ganimetini yönetirsin. En fazla dört yoldaş sahaya çıkar.</p></div><div class="guide-card"><b>◈ Altın ve ganimet</b><p>Her düşman altın bırakır; ara sıra ekipman da düşürür. Kullanmadığın eşyaları eriterek altın kazanabilir ya da uygun yuvaya kuşanabilirsin.</p></div><div class="guide-card"><b>✦ Dokuz yoldaş</b><p>Tank Savaşçı, Büyücü, Okçu, Şifacı Destek, Ağır Tank, Hançer Ustası, Kara Büyücü, Arbaletçi ve Ölü Çağıran arasından takımını seç.</p></div><div class="guide-card"><b>◇ Nadirlikler</b><p>Sıradan · Sıra dışı · Nadir · Destansı · Efsanevi · Mitik · Yıldız · Ay · Güneş · Hiçlik. Nadir eşyalar daha güçlü özellikler ve daha yüksek eritme bedeli sağlar.</p></div><div class="guide-card"><b>⌂ Karargâh geliştirmeleri</b><p>Yoldaş ayrıntılarından seviye, can, saldırı ve savunma eğitimi al. Ekipmanları silah, zırh ve tılsım yuvalarına takarak özellikleri artır.</p></div><div class="guide-card"><b>☾ Dalga ödülleri</b><p>Bir dalgadaki düşmanlar yenilince yeni dalga başlar. İlerledikçe rakipler sertleşir; altın ödülü ve nadir ganimet ihtimali de artar.</p></div></div>`}
function render(){updateGold();$('#wave').textContent=String(state.wave).padStart(2,'0');$('#kills').textContent=state.kills;renderRoster();document.querySelectorAll('.tab').forEach(t=>t.classList.toggle('active',t.dataset.tab===state.tab));if(state.tab==='inventory')renderInventory();if(state.tab==='equipment')renderEquipment();if(state.tab==='guide')renderGuide();if(state.tab==='hero')renderHero()}
function slotFor(type){return [0,3,5,6].includes(type)?0:[1,4,7,10].includes(type)?1:2}
function equip(){let i=state.inventory.find(x=>x.id===state.selectedItem);if(!i)return;let h=heroes.find(a=>a.id===state.selectedHero),slot=slotFor(i.type),old=state.equipped[h.id][slot];if(old)state.inventory.push(old);state.equipped[h.id][slot]=i;state.inventory=state.inventory.filter(a=>a.id!==i.id);state.selectedItem=null;toast(names[i.type]+' '+h.name+' tarafından kuşanıldı.');render()}
function melt(){let i=state.inventory.find(x=>x.id===state.selectedItem);if(!i)return;let g=meltValue(i);state.gold+=g;state.inventory=state.inventory.filter(a=>a.id!==i.id);state.selectedItem=null;updateGold();toast(names[i.type]+' eritildi: +'+g+' altın');render()}
function toggleDeploy(h){if(h.deployed){if(heroes.filter(x=>x.deployed).length<=1){toast('En az bir yoldaş sahada kalmalı.');return}h.deployed=false;toast(h.name+' görevden ayrıldı.')}else if(heroes.filter(x=>x.deployed).length>=4){toast('Sahada en fazla 4 yoldaş olabilir.');return}else if(state.gold<h.cost){toast('Göreve almak için '+h.cost+' altın gerekli.');return}else{state.gold-=h.cost;h.deployed=true;toast(h.name+' sefere katıldı! (-'+h.cost+' altın)')}state.tab='hero';render()}
function upgrade(h,kind){let cost=kind==='level'?35+h.level*20:kind==='atk'?30+h.level*12:25+h.level*10;if(state.gold<cost){toast('Yeterli altın yok.');return}state.gold-=cost;if(kind==='level')h.level++;else h[kind]+=kind==='hp'?20:kind==='atk'?4:3;toast(h.name+' geliştirildi: '+(kind==='level'?'Seviye '+h.level:kind==='hp'?'Can':kind==='atk'?'Saldırı':'Savunma')+'!');render()}
document.querySelectorAll('.tab').forEach(t=>t.onclick=()=>{state.tab=t.dataset.tab;state.selectedItem=null;render()});document.querySelectorAll('.speed-btn').forEach(b=>b.onclick=()=>{state.speed=Number(b.dataset.speed);document.querySelectorAll('.speed-btn').forEach(x=>x.classList.toggle('active',x===b))});$('#resetBtn').onclick=()=>{if(confirm('Seferi baştan başlatmak istiyor musun?'))location.reload()};$('#soundBtn').onclick=()=>toast('Bu ön izleme sessizdir; savaş otomatik sürüyor.');

const canvas=$('#battle'),ctx=canvas.getContext('2d');let cw=900,ch=360,lastFrame=0,spawnClock=0,wavePause=0,waveKills=0,nextEnemy=1,sceneTime=0;let enemies=[],effects=[],floaters=[];const runtime=Object.fromEntries(heroes.map(h=>[h.id,{hp:totalStat(h,'hp'),cool:Math.random()*.7,dead:0,flash:0}]));
function resizeCanvas(){const r=canvas.getBoundingClientRect(),d=Math.min(devicePixelRatio||1,2);canvas.width=Math.floor(r.width*d);canvas.height=Math.floor(r.height*d);cw=canvas.width;ch=canvas.height;ctx.setTransform(1,0,0,1,0,0)}window.addEventListener('resize',resizeCanvas);resizeCanvas();
function makeEnemy(){let hp=55+state.wave*16;enemies.push({id:nextEnemy++,x:cw+20,y:ch*.69+(Math.random()-.5)*8,hp,max:hp,atk:7+state.wave*1.2,speed:14+Math.random()*5,cool:.6+Math.random(),flash:0,type:Math.random()<.25?'shaman':'raider',seed:Math.random()*10})}
for(let i=0;i<3;i++){makeEnemy();enemies[i].x=cw*(.62+i*.14)}
function rounded(x,y,w,h,r,color){ctx.fillStyle=color;ctx.beginPath();ctx.roundRect(x,y,w,h,r);ctx.fill()}
function drawPine(x,y,s,color){ctx.fillStyle='#594d3b';ctx.fillRect(x-s*.08,y-s*.08,s*.16,s*.5);ctx.fillStyle=color;for(let i=0;i<3;i++){let yy=y-s*(.8-i*.23);ctx.beginPath();ctx.moveTo(x,yy-s*.3);ctx.lineTo(x-s*(.35-i*.045),yy+s*.22);ctx.lineTo(x+s*(.35-i*.045),yy+s*.22);ctx.closePath();ctx.fill()}}
function drawBackground(){let g=ctx.createLinearGradient(0,0,0,ch);g.addColorStop(0,'#263d3d');g.addColorStop(.55,'#566653');g.addColorStop(1,'#293b31');ctx.fillStyle=g;ctx.fillRect(0,0,cw,ch);let sunX=cw*.73,sunY=ch*.22;ctx.fillStyle='#e6c87622';ctx.beginPath();ctx.arc(sunX,sunY,45,0,Math.PI*2);ctx.fill();ctx.fillStyle='#eed591';ctx.beginPath();ctx.arc(sunX,sunY,19,0,Math.PI*2);ctx.fill();ctx.fillStyle='#a8b98a';ctx.beginPath();ctx.moveTo(0,ch*.58);ctx.quadraticCurveTo(cw*.22,ch*.32,cw*.43,ch*.57);ctx.quadraticCurveTo(cw*.72,ch*.31,cw,ch*.53);ctx.lineTo(cw,ch);ctx.lineTo(0,ch);ctx.fill();ctx.fillStyle='#536d50';ctx.beginPath();ctx.moveTo(0,ch*.69);ctx.quadraticCurveTo(cw*.27,ch*.45,cw*.5,ch*.68);ctx.quadraticCurveTo(cw*.72,ch*.47,cw,ch*.66);ctx.lineTo(cw,ch);ctx.lineTo(0,ch);ctx.fill();for(let i=0;i<18;i++){let x=(i*173+31)%cw,y=ch*(.51+((i*37)%15)/100),s=ch*(.1+((i*13)%10)/100);drawPine(x,y,s,i%2?'#314b3e':'#3e5a44')}ctx.fillStyle='#273a2e';ctx.fillRect(0,ch*.76,cw,ch*.24);ctx.fillStyle='#65734b';for(let i=0;i<Math.floor(cw/38);i++){let x=i*38+((i%3)*6),y=ch*.77+(i%4)*4;ctx.fillRect(x,y,18,3);ctx.fillRect(x+8,y-4,2,4)}ctx.fillStyle='#d3c080';ctx.globalAlpha=.22;ctx.fillRect(0,ch*.757,cw,2);ctx.globalAlpha=1}
