function nearestEnemy(x){let best=null,dist=Infinity;for(let e of enemies){let d=Math.abs(e.x-x);if(d<dist){dist=d;best=e}}return best}
function combatStep(dt){sceneTime+=dt;spawnClock+=dt;for(let h of heroes){let r=runtime[h.id];if(r.dead>0){r.dead-=dt;if(r.dead<=0){r.hp=totalStat(h,'hp');r.dead=0;toast(h.name+' yeniden savaşa katıldı.')}continue}if(!h.deployed)continue;r.hp=Math.min(r.hp,totalStat(h,'hp'));r.cool-=dt;r.flash=Math.max(0,r.flash-dt);let idx=heroes.filter(x=>x.deployed).indexOf(h),x=cw*(.12+idx*.065),target=nearestEnemy(x);if(target&&Math.abs(target.x-x)<cw*.38&&r.cool<=0){let dmg=totalStat(h,'atk')*(h.id==='dagger'&&target.hp<target.max*.4?1.6:1)*(h.id==='mage'?.9:1);target.hp-=dmg;target.flash=.12;r.cool=h.id==='archer'||h.id==='xbow'?.82:h.id==='mage'||h.id==='darkmage'?1.12:.98;effects.push({x1:x+12,y1:ch*.69-27,x2:target.x,y2:target.y-26,t:.16,max:.16,color:h.id==='mage'||h.id==='darkmage'?'#d898e7':h.id==='healer'?'#9ae0b0':'#f1d68b'});floaters.push({x:target.x,y:target.y-40,text:'-'+Math.round(dmg),t:.8,color:'#f2d39a'});if(h.id==='healer'){let low=heroes.filter(a=>a.deployed&&!runtime[a.id].dead).sort((a,b)=>runtime[a.id].hp/totalStat(a,'hp')-runtime[b.id].hp/totalStat(b,'hp'))[0];if(low){let lr=runtime[low.id];lr.hp=Math.min(totalStat(low,'hp'),lr.hp+8);effects.push({x1:x,y1:ch*.68-22,x2:cw*(.12+heroes.filter(a=>a.deployed).indexOf(low)*.065),y2:ch*.69-30,t:.2,max:.2,color:'#8de6bd'})}}}}
