function renderInventory(){let chosen=s.inv.find(i=>i.id===s.item);$('#content').innerHTML=`<div class="invhead"><span>Bulunan ganimetler · ${s.inv.length} eşya</span><button class="btn" id="sort">NADİRE GÖRE SIRALA ↕</button></div><div class="items">${s.inv.length?s.inv.map(i=>`<div class="item ${s.item===i.id?'sel':''}" data-item="${i.id}" style="--r:${colors[i.r]}"><div class="itemicon">${icons[i.type]}</div><div class="itemname">${gear[i.type]}</div><div class="meta">${rarities[i.r]} · Sv.${i.l}</div></div>`).join(''):'<div class="empty">Envanter boş. Düşmanları yenerek ganimet topla.</div>'}</div><div class="itemdetails">${chosen?`<div class="detail"><strong style="color:${colors[chosen.r]}">${gear[chosen.type]} · ${rarities[chosen.r]}</strong><small>Sv.${chosen.l} · ${gtype[chosen.type]} · ${gstats[chosen.type]}</small></div><div class="actions"><button class="btn primary" id="equip">KUŞAN</button><button class="btn red" id="melt">ERİT · +${12+chosen.l*5+chosen.r*9}◈</button></div>`:`<div class="detail"><strong>Eşya seçilmedi</strong><small>Kuşanmak veya eritmek için bir ganimet seç.</small></div><span class="count">${s.inv.length} EŞYA</span>`}</div>`;document.querySelectorAll('[data-item]').forEach(e=>e.onclick=()=>{s.item=Number(e.dataset.item);renderInventory()});$('#sort').onclick=()=>{s.inv.sort((a,b)=>b.r-a.r);renderInventory()};$('#equip')?.addEventListener('click',equip);$('#melt')?.addEventListener('click',melt)}
function renderEquipment(){let h=heroes.find(a=>a.id===s.hero),slots=['Silah','Zırh','Tılsım'];$('#content').innerHTML=`<div class="invhead"><span>${h.name} · Kuşanılmış ekipman</span><span class="count">${h.cls}</span></div><div class="slots">${slots.map((name,n)=>{let item=s.equip[h.id][n];return `<div class="slot"><div class="meta">${name}</div><div class="itemicon" style="color:${item?colors[item.r]:'#829188'}">${item?icons[item.type]:'◇'}</div><b>${item?gear[item.type]:'Boş yuva'}</b><small>${item?rarities[item.r]+' · '+gstats[item.type]:'Envanterden kuşan'}</small>${item?`<button class="btn unequip" data-slot="${n}">ÇIKAR</button>`:''}</div>`}).join('')}</div><div class="itemdetails"><div class="detail"><strong>Etkin özellikler</strong><small>Can ${stat(h,'hp')} · Saldırı ${stat(h,'atk')} · Savunma ${stat(h,'def')}</small></div><span class="count">${worn(h).length} / 3 YUVA</span></div>`;document.querySelectorAll('.unequip').forEach(b=>b.onclick=()=>{let n=Number(b.dataset.slot),item=s.equip[h.id][n];s.inv.push(item);s.equip[h.id][n]=null;say(gear[item.type]+' envantere taşındı.');render()})}
function renderGuide(){$('#content').innerHTML=`<div class="invhead"><span>SEFER NOTLARI · KÜL ORMANI</span><span class="count">OTOMATİK SAVAŞ</span></div><div class="guide"><div class="guidecard"><b>⚔ Sefer nasıl işler?</b><p>Yoldaşların düşmanları kendi başlarına bulur ve saldırır. Sen ekibini kurar, geliştirir ve ganimetini yönetirsin. En fazla dört yoldaş sahaya çıkar.</p></div><div class="guidecard"><b>◈ Altın ve ganimet</b><p>Her düşman altın bırakır; ara sıra ekipman da düşürür. Kullanmadığın eşyaları eriterek altın kazanabilir ya da uygun yuvaya kuşanabilirsin.</p></div><div class="guidecard"><b>✦ Dokuz yoldaş</b><p>Tank Savaşçı, Büyücü, Okçu, Şifacı Destek, Ağır Tank, Hançer Ustası, Kara Büyücü, Arbaletçi ve Ölü Çağıran arasından takımını seç.</p></div><div class="guidecard"><b>◇ Nadirlikler</b><p>Sıradan · Sıra dışı · Nadir · Destansı · Efsanevi · Mitik · Yıldız · Ay · Güneş · Hiçlik. Nadir eşyalar daha güçlü özellikler ve daha yüksek eritme bedeli sağlar.</p></div><div class="guidecard"><b>⌂ Karargâh geliştirmeleri</b><p>Yoldaş ayrıntılarından seviye, can, saldırı ve savunma eğitimi al. Ekipmanları silah, zırh ve tılsım yuvalarına takarak özellikleri artır.</p></div><div class="guidecard"><b>☾ Dalga ödülleri</b><p>Bir dalgadaki düşmanlar yenilince yeni dalga başlar. İlerledikçe rakipler sertleşir; altın ödülü ve nadir ganimet ihtimali de artar.</p></div></div>`}
function render(){updateGold();$('#wave').textContent=String(s.wave).padStart(2,'0');$('#kills').textContent=s.kills;drawRoster();document.querySelectorAll('.tab').forEach(t=>t.classList.toggle('active',t.dataset.tab===s.tab));if(s.tab==='hero')renderHero();if(s.tab==='inventory')renderInventory();if(s.tab==='equipment')renderEquipment();if(s.tab==='guide')renderGuide()}
function equip(){let i=s.inv.find(a=>a.id===s.item);if(!i)return;let h=heroes.find(a=>a.id===s.hero),n=slot(i.type),old=s.equip[h.id][n];if(old)s.inv.push(old);s.equip[h.id][n]=i;s.inv=s.inv.filter(a=>a.id!==i.id);s.item=null;say(gear[i.type]+' '+h.name+' tarafından kuşanıldı.');render()}
function melt(){let i=s.inv.find(a=>a.id===s.item);if(!i)return;let value=12+i.l*5+i.r*9;s.gold+=value;s.inv=s.inv.filter(a=>a.id!==i.id);s.item=null;say(gear[i.type]+' eritildi: +'+value+' altın');render()}
function deploy(h){if(h.deployed){if(heroes.filter(a=>a.deployed).length<=1){say('En az bir yoldaş sahada kalmalı.');return}h.deployed=false;say(h.name+' görevden ayrıldı.')}else if(heroes.filter(a=>a.deployed).length>=4){say('Sahada en fazla 4 yoldaş olabilir.');return}else if(s.gold<h.cost){say('Göreve almak için '+h.cost+' altın gerekli.');return}else{s.gold-=h.cost;h.deployed=true;combat[h.id].hp=stat(h,'hp');say(h.name+' sefere katıldı! (-'+h.cost+' altın)')}render()}
function upgrade(h,k){let cost=k==='level'?35+h.level*20:k==='atk'?30+h.level*12:25+h.level*10;if(s.gold<cost){say('Yeterli altın yok.');return}s.gold-=cost;if(k==='level')h.level++;else h[k]+=k==='hp'?20:k==='atk'?4:3;if(combat[h.id])combat[h.id].hp=Math.min(stat(h,'hp'),combat[h.id].hp+(k==='hp'?20:0));say(h.name+' geliştirildi: '+(k==='level'?'Seviye '+h.level:k==='hp'?'Can':k==='atk'?'Saldırı':'Savunma')+'!');render()}
document.querySelectorAll('.tab').forEach(t=>t.onclick=()=>{s.tab=t.dataset.tab;s.item=null;render()});document.querySelectorAll('.speed').forEach(b=>b.onclick=()=>{s.speed=Number(b.dataset.speed);document.querySelectorAll('.speed').forEach(x=>x.classList.toggle('on',x===b))});$('#reset').onclick=()=>{if(confirm('Seferi baştan başlatmak istiyor musun?'))location.reload()};$('#sound').onclick=()=>say('Bu ön izleme sessizdir; savaş otomatik sürüyor.');
